function cleanNumber(e){return e&&parseFloat(String(e).replace(/,/g,"").trim())||0}async function loadSpreadsheetData(e,r){const t=`${e}_${r}`;if(DATA_BY_MONTH[t]&&DATA_BY_MONTH[t].isFetched)return!0;const a=localStorage.getItem(`TonyTit_Data_${t}`);if(a)try{return DATA_BY_MONTH[t]=JSON.parse(a),DATA_BY_MONTH[t].isFetched=!0,fetchAndUpdateInBackground(e,r,t),!0}catch(e){console.error("Cache parse error",e)}return await fetchAndUpdateInBackground(e,r,t)}async function fetchAndUpdateInBackground(e,r,t){try{const a=await fetch(`${window.APPS_SCRIPT_URL}?month=${e}&year=${r}`);if(!a.ok)throw new Error("Network error");const n=await a.json();if(n.raw&&n.raw.length>0){DATA_BY_MONTH[t]={rawJson:n.raw||[],adsJson:n.ads||[],marketingJson:n.marketing||[],isFetched:!0};try{localStorage.setItem(`TonyTit_Data_${t}`,JSON.stringify(DATA_BY_MONTH[t]))}catch(e){console.warn("LocalStorage quota exceeded, running from RAM only:",e)}return window.dispatchEvent(new CustomEvent("dashboardDataRefreshed",{detail:{month:e,year:r}})),!0}return!1}catch(e){return console.error("Background Fetch failed:",e),!1}}function preloadAdjacentMonths(e,r){const t=12===e?1:e+1,a=12===e?r+1:r;loadSpreadsheetData(1===e?12:e-1,1===e?r-1:r).catch(()=>{}),loadSpreadsheetData(t,a).catch(()=>{})}function parseRawData(e){const r=[];return e.forEach(e=>{const t=Object.values(e);if(t.length<5)return;const a=String(t[2]).trim().split("/");a.length>=2&&r.push({brand:String(t[0]).toUpperCase(),branch:String(t[1]).toUpperCase(),day:parseInt(a[0]),revenue:cleanNumber(t[4]),customers:cleanNumber(t[3])})}),r}function parseMarketingData(e){const r=[];return e?(e.forEach(e=>{const t=Object.values(e).map(String);t.length<8||t[0].toLowerCase().includes("cơ sở")||r.push({brand:t[0].toUpperCase().trim(),branch:t[1].toUpperCase().trim(),name:`${t[0]} ${t[1]}`,leads:cleanNumber(t[2]),phones:cleanNumber(t[3]),arrived:cleanNumber(t[4]),rate1:t[6],rate2:t[7]})}),r):r}function getUnifiedBranchData(e,r="all"){if(!e||!e.adsJson)return[];const t={};return e.adsJson.forEach(e=>{const a=Object.values(e);if(a.length<9)return;const n=String(a[0]).toUpperCase().trim(),c=String(a[1]).toUpperCase().trim();"all"!==r&&n!==r||(t[c]={brand:n,branch:c,revenue:cleanNumber(a[2]),target:cleanNumber(a[3]),customers:cleanNumber(a[5]),ads:cleanNumber(a[7]),breakeven:cleanNumber(a[8]),cir:0,percentKpi:0},t[c].cir=t[c].revenue>0?t[c].ads/t[c].revenue*100:0,t[c].percentKpi=t[c].target>0?t[c].revenue/t[c].target*100:0)}),Object.values(t)}